      {
        "event_id": "lite_evt_00084",
        "explanation": "Doctor warns against self-adjusting insulin and prioritizes hypoglycemia risk.",
        "quote": "不要自己随意加量胰岛素，继续按出院医嘱的原剂量注射就好，低血糖的风险比单次高血糖更危险"
      }
    ],
    "patient_family_realworld_adaptation": [
      {
        "event_id": "lite_evt_00064",
        "explanation": "Doctor acknowledges wait time and resource constraint and advises to bring all documents.",
        "quote": "您预约门诊的时候记得带齐所有这次住院的资料哦"
      }
    ]
  },
